// Radial burst. Every param() is a knob you can modulate.
param("count", 12, 1, 64);
param("spin", 0.2, 0, 2);
param("size", 48, 4, 160);

function draw(t) {
  background(0.05);
  translate(width / 2, height / 2);
  noStroke();
  const r = min(width, height) * 0.3;
  for (let i = 0; i < count; i++) {
    rotate(TAU / count + spin * t * 0.1);
    fill(hsl(i / count, 0.7, 0.6));
    circle(r * 1.2 + r * 0.4 * sin(t + i), 0, size);
  }
}

// Cubes on a ring. Every param() is a knob you can modulate.
param("count", 12, 1, 48);
param("radius", 1.2, 0.2, 3);
param("size", 0.25, 0.05, 0.8);
param("spin", 0.3, 0, 2);

function draw(t) {
  for (let i = 0; i < count; i++) {
    push();
    rotateY(TAU * i / count + spin * t);
    translate(radius, 0.3 * sin(t * 2 + i), 0);
    rotateX(t + i);
    fill(hsl(i / count, 0.65, 0.6));
    box(size);
    pop();
  }
}
